"""Gold labels are supplied fixtures, never estimates generated by the build."""

import hashlib
import json
import sqlite3

import pytest

from GSE.curation.lexicon_builder.engine import Assertion, propagate
from GSE.curation.lexicon_builder.evaluation import evaluate_build
from GSE.curation.lexicon_builder.evidence import Definition, Observation
from GSE.curation.lexicon_builder.foundation import BANKS
from GSE.curation.lexicon_builder.storage import open_build, store_entry, store_observations


@pytest.fixture
def dictionary(tmp_path):
    path = tmp_path / "build.db"
    conn = open_build(path)
    try:
        for entry_id, pos, values, sources in (
            ("a", "a", (("GOOD", 1), ("WANT", 0)), ("alpha", "beta")),
            ("b", "n", (("GOOD", -1),), ("beta",)),
            ("c", "v", (("GOOD", -1), ("GOOD", 1)), ("gamma",)),
            ("d", "n", (), ()),
            ("same-a", "a", (("GOOD", 1),), ("alpha",)),
        ):
            assertions = tuple(Assertion(bank, value, sources[0], entry_id, "dictionary") for bank, value in values)
            store_entry(
                conn, Definition(entry_id, "shared", pos, entry_id), propagate(BANKS, assertions, ()), assertions
            )
            store_observations(
                conn,
                tuple(
                    Observation(entry_id, source, entry_id + ":" + source, "dictionary", {}, "lexical")
                    for source in sources
                ),
            )
        conn.commit()
    finally:
        conn.close()
    return path


def gold(tmp_path, records):
    path = tmp_path / "gold.json"
    path.write_text(json.dumps({"format": "gse.lexicon-gold/1", "records": records}))
    return path


def label(entry_id="a", bank="GOOD", expected=1, **kwargs):
    return {"entry_id": entry_id, "bank": bank, "expected": expected, **kwargs}


def test_exact_identity_outcomes_and_overlapping_source_cohorts(dictionary, tmp_path):
    supplied = gold(
        tmp_path,
        [
            label(),
            label(bank="WANT", expected=0),
            label(bank="FEEL", expected=0),
            label("b"),
            label("c"),
            label("missing"),
        ],
    )
    before = dictionary.read_bytes()
    report = evaluate_build(dictionary, supplied)
    assert dictionary.read_bytes() == before
    assert report["code"] == "GOLD_EVALUATED"
    assert report["outcomes"] == {"IDENTIFIED_CORRECT": 2, "ABSTAINED": 1, "CONFLICT": 1, "WRONG": 1, "NOT_FOUND": 1}
    assert report["coverage"] == {"identified": 3, "total": 6, "fraction": 0.5}
    assert "accuracy" not in report
    assert "weighted" not in report
    assert report["per_bank"]["WANT"]["outcomes"]["IDENTIFIED_CORRECT"] == 1
    assert report["per_pos"]["adjective"]["total"] == 3
    assert report["per_pos"]["noun"]["outcomes"]["WRONG"] == 1
    assert report["per_pos"]["verb"]["outcomes"]["CONFLICT"] == 1
    assert report["per_source"]["alpha"]["total"] == 3
    assert report["per_source"]["beta"]["total"] == 4
    assert report["per_source"]["NOT_FOUND"]["outcomes"]["NOT_FOUND"] == 1
    assert report["gold"]["sha256"] == hashlib.sha256(supplied.read_bytes()).hexdigest()
    assert report["gold"]["origin"] == "SUPPLIED_LABELS"
    assert report["verification"] == "PUBLISHED_PROJECTION_ONLY"
    zero = next(record for record in report["records"] if record["bank"] == "WANT")
    silence = next(record for record in report["records"] if record["bank"] == "FEEL")
    assert zero["observed"] == 0 and silence["observed"] is None


def test_equal_coordinates_do_not_merge_gold_definition_identities(dictionary, tmp_path):
    report = evaluate_build(dictionary, gold(tmp_path, [label(), label("same-a")]))
    assert report["total"] == 2
    assert [record["entry_id"] for record in report["records"]] == ["a", "same-a"]


def test_unknown_id_never_falls_back_to_shared_lemma(dictionary, tmp_path):
    report = evaluate_build(dictionary, gold(tmp_path, [label("shared")]))
    assert report["records"][0]["code"] == "NOT_FOUND"
    assert report["records"][0]["observed"] is None


def test_no_linked_source_is_named_and_silence_is_abstention(dictionary, tmp_path):
    report = evaluate_build(dictionary, gold(tmp_path, [label("d")]))
    assert report["per_source"]["NO_LINKED_SOURCE"]["outcomes"]["ABSTAINED"] == 1


def test_weighted_and_unweighted_coverage_are_separate(dictionary, tmp_path):
    report = evaluate_build(
        dictionary, gold(tmp_path, [label(weight=3), label("b", weight=1), label("missing", weight=6)])
    )
    assert report["coverage"]["fraction"] == pytest.approx(2 / 3)
    assert report["weighted"]["coverage"] == {"identified": 4.0, "total": 10.0, "fraction": 0.4}
    assert report["weighted"]["outcomes"]["WRONG"] == 1.0
    assert report["per_source"]["beta"]["weighted"]["total"] == 4.0


def test_zero_weight_coverage_is_undefined(dictionary, tmp_path):
    report = evaluate_build(dictionary, gold(tmp_path, [label(weight=0)]))
    assert report["weighted"]["coverage"]["fraction"] is None
    assert report["coverage"]["fraction"] == 1.0


@pytest.mark.parametrize(
    "field,value,code",
    [
        ("entry_id", True, "INVALID_GOLD_DEFINITION_ID"),
        ("entry_id", "  ", "INVALID_GOLD_DEFINITION_ID"),
        ("bank", "NUMBER", "UNKNOWN_GOLD_BANK"),
        ("bank", "UNKNOWN", "UNKNOWN_GOLD_BANK"),
        ("bank", [], "UNKNOWN_GOLD_BANK"),
        ("expected", True, "INVALID_GOLD_TRIT"),
        ("expected", None, "INVALID_GOLD_TRIT"),
        ("expected", 1.0, "INVALID_GOLD_TRIT"),
        ("expected", "1", "INVALID_GOLD_TRIT"),
        ("expected", 2, "INVALID_GOLD_TRIT"),
        ("weight", True, "INVALID_GOLD_WEIGHT"),
        ("weight", -1, "INVALID_GOLD_WEIGHT"),
        ("weight", "1", "INVALID_GOLD_WEIGHT"),
        ("weight", 10**400, "INVALID_GOLD_WEIGHT"),
    ],
)
def test_malformed_gold_is_rejected(dictionary, tmp_path, field, value, code):
    record = label()
    record[field] = value
    with pytest.raises(ValueError, match=code):
        evaluate_build(dictionary, gold(tmp_path, [record]))


@pytest.mark.parametrize(
    "raw,code",
    [
        (
            '{"format":"gse.lexicon-gold/1","records":[{"entry_id":"a","bank":"GOOD","expected":1,"expected":-1}]}',
            "DUPLICATE_JSON_FIELD",
        ),
        (
            '{"format":"gse.lexicon-gold/1","records":[{"entry_id":"a","bank":"GOOD","expected":NaN}]}',
            "NONFINITE_JSON_VALUE",
        ),
        (
            '{"format":"gse.lexicon-gold/1","records":[{"entry_id":"a","bank":"GOOD","expected":1,"weight":1e999}]}',
            "INVALID_GOLD_WEIGHT",
        ),
        ('{"format":"gse.lexicon-gold/1","records":[]}', "EMPTY_OR_INVALID_GOLD_RECORDS"),
        ('{"format":"gse.lexicon-gold/1","records":{}}', "EMPTY_OR_INVALID_GOLD_RECORDS"),
        ('{"format":"gse.lexicon-gold/1","records":[null]}', "INVALID_GOLD_RECORD"),
        ('{"format":"future","records":[]}', "INVALID_GOLD_FORMAT"),
        ('{"format":"gse.lexicon-gold/1","records":[],"accuracy":1}', "INVALID_GOLD_FORMAT"),
    ],
)
def test_strict_json_gold_boundary(dictionary, tmp_path, raw, code):
    path = tmp_path / "invalid.json"
    path.write_text(raw)
    with pytest.raises(ValueError, match=code):
        evaluate_build(dictionary, path)


@pytest.mark.parametrize(
    "records,code",
    [
        ([label(), label()], "DUPLICATE_GOLD_CELL"),
        ([label(), label(expected=-1)], "DUPLICATE_GOLD_CELL"),
        ([label(weight=1), label("b")], "INCOMPLETE_GOLD_WEIGHTS"),
        ([label(weight=1e308), label("b", weight=1e308)], "INVALID_TOTAL_GOLD_WEIGHT"),
        ([{**label(), "comment": "unsupported"}], "UNKNOWN_GOLD_FIELD"),
        ([{"entry_id": "a", "bank": "GOOD"}], "INVALID_GOLD_RECORD"),
    ],
)
def test_gold_cannot_double_count_or_hide_incomplete_labels(dictionary, tmp_path, records, code):
    with pytest.raises(ValueError, match=code):
        evaluate_build(dictionary, gold(tmp_path, records))


def test_missing_files_do_not_create_a_database(dictionary, tmp_path):
    missing = tmp_path / "absent.db"
    with pytest.raises(ValueError, match="BUILD_NOT_FOUND"):
        evaluate_build(missing, gold(tmp_path, [label()]))
    assert not missing.exists()
    with pytest.raises(ValueError, match="GOLD_NOT_FOUND"):
        evaluate_build(dictionary, tmp_path / "missing-gold.json")


def test_unknown_build_format_rejected(dictionary, tmp_path):
    conn = sqlite3.connect(dictionary)
    try:
        conn.execute("UPDATE builder_metadata SET value=? WHERE key='format'", (json.dumps("future/99"),))
        conn.commit()
    finally:
        conn.close()
    with pytest.raises(ValueError, match="UNSUPPORTED_BUILD_FORMAT"):
        evaluate_build(dictionary, gold(tmp_path, [label()]))


def test_corrupted_published_values_are_not_scored_as_predictions(dictionary, tmp_path):
    conn = sqlite3.connect(dictionary)
    try:
        conn.execute("UPDATE primitive_values SET value=0.5 WHERE primitive='GOOD'")
        conn.commit()
    finally:
        conn.close()
    with pytest.raises(ValueError, match="INVALID_PUBLISHED_ASSIGNMENT"):
        evaluate_build(dictionary, gold(tmp_path, [label()]))


@pytest.mark.parametrize("invalid", [False, True])
def test_readonly_connection_closes_on_success_and_error(dictionary, tmp_path, monkeypatch, invalid):
    original = sqlite3.connect
    opened = []
    if invalid:
        connection = original(dictionary)
        try:
            connection.execute("UPDATE builder_metadata SET value=? WHERE key='format'", (json.dumps("future/99"),))
            connection.commit()
        finally:
            connection.close()

    def tracked(*args, **kwargs):
        assert args[0].endswith("?mode=ro")
        result = original(*args, **kwargs)
        opened.append(result)
        return result

    monkeypatch.setattr(sqlite3, "connect", tracked)
    if invalid:
        with pytest.raises(ValueError, match="UNSUPPORTED_BUILD_FORMAT"):
            evaluate_build(dictionary, gold(tmp_path, [label()]))
    else:
        evaluate_build(dictionary, gold(tmp_path, [label()]))
    for conn in opened:
        with pytest.raises(sqlite3.ProgrammingError, match="closed"):
            conn.execute("SELECT 1")
